            emailValue: emailInput.value,
            passwordValue: passwordInput.value,
            emailErrorVisible: emailError.classList.contains('show'),
            emailErrorText: emailError.textContent,
            passwordErrorVisible: passwordError.classList.contains('show'),
            passwordErrorText: passwordError.textContent
        };
    } catch (e) {
        results.test1_empty = { error: e.message };
    }

