    try {
        const emailInput = document.getElementById('email');
        const passwordInput = document.getElementById('password');
        const loginBtn = document.getElementById('loginBtn');

        emailInput.value = 'test@';
        passwordInput.value = 'password123';

        emailInput.dispatchEvent(new Event('input', { bubbles: true }));
        passwordInput.dispatchEvent(new Event('input', { bubbles: true }));

        loginBtn.click();

        await new Promise(r => setTimeout(r, 100));

        const emailError = document.getElementById('emailError');

        results.test2_invalid_email = {
            emailValue: emailInput.value,
            passwordValue: passwordInput.value,
            emailErrorVisible: emailError.classList.contains('show'),
            emailErrorText: emailError.textContent,
            isValidEmail: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailInput.value)
        };
    } catch (e) {
        results.test2_invalid_email = { error: e.message };
    }

    // Test 3: Wrong password
    try {
        const emailInput = document.getElementById('email');
        const passwordInput = document.getElementById('password');
        const loginBtn = document.getElementById('loginBtn');

        // Need to clear errors first
        const emailError = document.getElementById('emailError');
        const passwordError = document.getElementById('passwordError');
        emailError.classList.remove('show');
        passwordError.classList.remove('show');
        emailInput.classList.remove('error');
        passwordInput.classList.remove('error');

        emailInput.value = 'test@example.com';
        passwordInput.value = 'wrongpassword';

        emailInput.dispatchEvent(new Event('input', { bubbles: true }));
        passwordInput.dispatchEvent(new Event('input', { bubbles: true }));

        loginBtn.click();

        // Wait for login attempt (500ms delay in code)
        await new Promise(r => setTimeout(r, 600));

        // Check if still on login page or redirected
        const loginForm = document.getElementById('loginForm');
        const userInfo = document.getElementById('userInfo');

        results.test3_wrong_password = {
            emailValue: emailInput.value,
            passwordValue: passwordInput.value,
            loginFormVisible: loginForm.style.display !== 'none',
            userInfoVisible: userInfo.classList.contains('show'),
            alertTriggered: window.lastAlert || 'no alert captured'
        };
    } catch (e) {
        results.test3_wrong_password = { error: e.message };
    }

    // Test 4: Correct password
    try {
        const emailInput = document.getElementById('email');
        const passwordInput = document.getElementById('password');
        const loginBtn = document.getElementById('loginBtn');

        emailInput.value = 'test@example.com';
        passwordInput.value = 'password123';

        emailInput.dispatchEvent(new Event('input', { bubbles: true }));
        passwordInput.dispatchEvent(new Event('input', { bubbles: true }));

        loginBtn.click();

        await new Promise(r => setTimeout(r, 600));

        const loginForm = document.getElementById('loginForm');
        const userInfo = document.getElementById('userInfo');
        const userEmail = document.getElementById('userEmail');

        const storageKey = 'macbot_e2e_s2_parallel_fc45ecd3b62c_login';
